write_file('backend/prisma/schema.prisma', 'generator client {\n  binaryTargets = ["native", "linux-musl-openssl-3.0.x"]\n  provider = "prisma-client-js"\n}\n\ndatasource db {\n  provider = "mongodb"\n  url      = env("DATABASE_URL")\n}\n\nenum Role {\n  USER\n  ADMIN\n  SUPERADMIN\n}\n\nenum VideoCategory {\n  SHOW_PIECE\n  WORKING_MODEL\n  SCIENCE_EXPERIMENT\n  MAGIC_SCIENCE\n  LIFE_HACK\n  ELECTRONICS\n}\n\nenum VideoApprovalStatus {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\nenum ApprovalAction {\n  SUBMITTED\n  APPROVED\n  REJECTED\n  REOPENED\n}\n\nenum GuardianType {\n  PARENT\n  SCHOOL\n  TLAB\n  COMMUNITY\n}\n\ntype ScoreHistory {\n  time         DateTime\n  updatedScore Int\n  reason       String?\n}\n\ntype ChildScoreHistory {\n  time         DateTime\n  updatedScore Int\n  reason       String?\n}\n\ntype GuardianInfo {\n  institutionName String?\n  address         String?\n  city            String?\n  state           String?\n  pincode         String?\n  isVerified      Boolean\n}\n\nmodel User {\n  id            String         @id @default(auto()) @map("_id") @db.ObjectId\n  email         String         @unique\n  passwordHash  String\n  name          String\n  age           Int\n  // Daily Quest streak (Aug 2026) — see DailyQuestProgress model. Streak\n  // increments once per real quest-completing day; lastQuestDate uses\n  // "YYYY-MM-DD" so continuity can be checked with a plain string compare,\n  // no timezone-math needed.\n  currentStreak Int            @default(0)\n  lastQuestDate String?\n  role          Role           @default(USER)\n  phoneNumber   String?\n  createdAt     DateTime       @default(now())\n  updatedAt     DateTime       @updatedAt\n  refreshToken  String?\n  score         Int            @default(0)\n  scoreHistory  ScoreHistory[]\n  profilePhoto  String?\n  parentName   String?\n  parentPhone  String?\n  guardianEmail String?\n  emailVerified Boolean  @default(false)\n  // ── Contact verification (email + phone), on-demand, not blocking ──────\n  // Verification is never required at registration — it can be requested\n  // any time by the account holder. Changing a contact that is currently\n  // VERIFIED requires approval (OTP sent to the OLD verified contact, or\n  // manual admin approval if that\'s unreachable) before it takes effect.\n  // Changing an UNVERIFIED contact applies immediately — nothing to protect.\n  phoneVerified            Boolean   @default(false)\n  verificationOtpHash      String?\n  verificationOtpExpiry    DateTime?\n  verificationOtpTarget    String?   // \'email\' | \'phone\' — which field the pending OTP is for\n  pendingEmail             String?   // new email awaiting old-contact confirmation\n  pendingPhone             String?   // new phone awaiting old-contact confirmation\n  contactChangeApprovalFor String?   // \'email\' | \'phone\' | null — set when the old contact\n                                      // is unreachable and an admin must manually approve\n  contactChangeRequestedAt DateTime?\n  about        String?\n  grade        String?\n  schoolName   String?\n  city         String?\n  interests    String[]  @default([])\n  isMentor      Boolean        @default(false)\n  mentorType    GuardianType?\n  guardianInfo  GuardianInfo?\n  children      ChildProfile[]\n  comments      Comment[]\n  orders        Order[]\n  likes         Like[]\n  projects      Project[]\n  wallet        Wallet?\n  walletId      String?        @db.ObjectId\n  videoViews    VideoView[]\n  videoLikes    VideoLike[]\n  videoComments VideoComment[]\n\n  @@map("users")\n}\n\nmodel ChildProfile {\n  id           String              @id @default(auto()) @map("_id") @db.ObjectId\n  guardianId   String              @db.ObjectId\n  guardian     User                @relation(fields: [guardianId], references: [id], onDelete: Cascade)\n  name         String\n  age          Int\n  grade        String?\n  avatar       String?\n  pinHash      String\n  linkedUserId String?  @db.ObjectId\n  score        Int                 @default(0)\n  scoreHistory ChildScoreHistory[]\n  isActive     Boolean             @default(true)\n  createdAt    DateTime            @default(now())\n  updatedAt    DateTime            @updatedAt\n  videoUploads ChildVideo[]\n  orders       ChildOrder[]\n\n  @@index([guardianId])\n  @@map("child_profiles")\n}\n\nmodel ChildVideo {\n  id             String       @id @default(auto()) @map("_id") @db.ObjectId\n  childProfileId String       @db.ObjectId\n  child          ChildProfile @relation(fields: [childProfileId], references: [id], onDelete: Cascade)\n  projectId      String?      @db.ObjectId\n  youtubeUrl     String?\n  title          String\n  status         String       @default("pending")\n  uploadedBy     String       @db.ObjectId\n  createdAt      DateTime     @default(now())\n\n  @@index([childProfileId])\n  @@map("child_videos")\n}\n\nmodel PendingVideo {\n  id                    String                    @id @default(auto()) @map("_id") @db.ObjectId\n  title                 String\n  description           String\n  category              VideoCategory\n  tags                  String[]\n  localPath             String\n  originalName          String?\n  fileSize              Int?\n  mimeType              String?\n  uploadedById          String                    @db.ObjectId\n  status                VideoApprovalStatus       @default(PENDING)\n  approvalNotes         String?\n  approvedById          String?                   @db.ObjectId\n  approvedAt            DateTime?\n  rejectedById          String?                   @db.ObjectId\n  rejectedAt            DateTime?\n  rejectionReason       String?\n  youtubeVideoId        String?\n  youtubeUrl            String?\n  privacyStatus         String                    @default("public")\n  submittedAt           DateTime                  @default(now())\n  updatedAt             DateTime                  @updatedAt\n  auditTrail            VideoApprovalAudit[]\n\n  @@index([status])\n  @@index([uploadedById])\n  @@index([category])\n  @@index([approvedAt])\n  @@index([rejectedAt])\n  @@map("pending_videos")\n}\n\nmodel VideoApprovalAudit {\n  id                String           @id @default(auto()) @map("_id") @db.ObjectId\n  pendingVideoId    String           @db.ObjectId\n  pendingVideo      PendingVideo     @relation(fields: [pendingVideoId], references: [id], onDelete: Cascade)\n  action            ApprovalAction\n  actionById        String           @db.ObjectId\n  actionByName      String?\n  actionByEmail     String?\n  notes             String?\n  changesSummary    String?\n  ipAddress         String?\n  userAgent         String?\n  timestamp         DateTime         @default(now())\n\n  @@index([pendingVideoId])\n  @@index([action])\n  @@index([timestamp])\n  @@index([actionById])\n  @@map("video_approval_audits")\n}\n\nmodel ChildOrder {\n  id             String       @id @default(auto()) @map("_id") @db.ObjectId\n  childProfileId String       @db.ObjectId\n  child          ChildProfile @relation(fields: [childProfileId], references: [id], onDelete: Cascade)\n  orderId        String       @db.ObjectId\n  createdAt      DateTime     @default(now())\n\n  @@index([childProfileId])\n  @@map("child_orders")\n}\n\nmodel VideoView {\n  id        String   @id @default(auto()) @map("_id") @db.ObjectId\n  videoId   String\n  userId    String   @db.ObjectId\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  createdAt DateTime @default(now())\n\n  @@unique([videoId, userId])\n  @@index([videoId])\n  @@index([userId])\n  @@map("video_views")\n}\n\nmodel VideoLike {\n  id        String   @id @default(auto()) @map("_id") @db.ObjectId\n  videoId   String\n  userId    String   @db.ObjectId\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  category  String\n  createdAt DateTime @default(now())\n\n  @@unique([videoId, userId, category])\n  @@index([videoId])\n  @@index([userId])\n  @@map("video_likes")\n}\n\nmodel VideoComment {\n  id               String   @id @default(auto()) @map("_id") @db.ObjectId\n  videoId          String\n  userId           String   @db.ObjectId\n  user             User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  comment          String\n  createdAt        DateTime @default(now())\n  postedToYouTube  Boolean  @default(false)\n  youtubeCommentId String?\n\n  @@index([videoId])\n  @@index([userId])\n  @@map("video_comments")\n}\n\nmodel ProjectCategory {\n  id       String    @id @default(auto()) @map("_id") @db.ObjectId\n  name     String    @unique\n  icon     String    @default("📦")\n  imageUrl String?\n  projects Project[]\n\n  @@map("projectcategories")\n}\n\nmodel Project {\n  id          String            @id @default(auto()) @map("_id") @db.ObjectId\n  title       String\n  description String\n  startDate   DateTime\n  endDate     DateTime\n  thumbnail   String\n  video       Video\n  materials   ProjectMaterial[]\n  userId      String            @db.ObjectId\n  user        User              @relation(fields: [userId], references: [id], onDelete: Cascade)\n  categoryId  String            @db.ObjectId\n  category    ProjectCategory   @relation(fields: [categoryId], references: [id])\n  likes       Like[]\n  comments    Comment[]\n  status      String            @default("pending")\n  aiVerdict   String?\n  aiReason    String?\n  aiConfidence Float?\n  aiReviewedAt DateTime?\n  // Shared/group projects — additional children working on this project\n  // alongside the owner (userId above). Set only at upload time (never\n  // editable afterward — collaborators can only be added while planning,\n  // before the video is uploaded). Goins split equally across owner +\n  // all collaborators on admin approval — see approveProject().\n  collaborators ProjectCollaborator[]\n  // STEAM Challenge this project was made for (optional). Set only at\n  // upload time, same as collaborators — a child picks a challenge while\n  // planning. On admin approval, the challenge\'s goinsReward is awarded\n  // IN ADDITION to the normal upload-approval Goins (split the same way\n  // across owner + collaborators) — see publishAndAwardProject().\n  challengeId            String?   @db.ObjectId\n  challengeGoinsAwarded   Int?      // audit trail — set once, at approval\n  createdAt   DateTime          @default(now())\n  updatedAt   DateTime          @updatedAt\n\n  @@index([userId])\n  @@index([categoryId])\n  @@index([status])\n  @@index([challengeId])\n  @@map("projects")\n}\n\ntype ProjectCollaborator {\n  userId String @db.ObjectId\n  name   String // snapshot at time of upload, for display without an extra join\n}\n\ntype Video {\n  url        String\n  uploadedAt String?\n}\n\ntype ProjectMaterial {\n  productId String  @db.ObjectId\n  name      String?\n  quantity  Int\n}\n\n// In-app notifications — used to REPLACE email for anything that isn\'t a\n// literal OTP or a message to someone with no login (password reset, shop\n// send-to-parent). Admin broadcasts and AI-review alerts write here instead\n// of sending an email to every recipient. Surfaced via GET /users/me/notifications\n// (child/mentor) and GET /admin/notifications (admin), merged with the\n// existing computed comment/like feed — no separate UI needed.\nmodel Notification {\n  id        String   @id @default(auto()) @map("_id") @db.ObjectId\n  userId    String   @db.ObjectId // who sees this notification\n  type      String   // \'broadcast\' | \'ai_review_unsure\' | \'announcement\' | ...\n  emoji     String   @default("🔔")\n  message   String\n  link      String?  // optional deep-link, e.g. a project id or admin queue path\n  read      Boolean  @default(false)\n  createdAt DateTime @default(now())\n\n  @@index([userId])\n  @@map("notifications")\n}\n\nmodel Comment {\n  id            String   @id @default(auto()) @map("_id") @db.ObjectId\n  commentedBy   User     @relation(fields: [commentedById], references: [id], onDelete: Cascade)\n  commentedById String   @db.ObjectId\n  content       String\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n  project       Project  @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  projectId     String   @db.ObjectId\n\n  @@unique([projectId, commentedById])\n  @@index([commentedById])\n  @@index([projectId])\n  @@map("comments")\n}\n\nmodel Like {\n  id        String   @id @default(auto()) @map("_id") @db.ObjectId\n  likedBy   User     @relation(fields: [likedById], references: [id], onDelete: Cascade)\n  likedById String   @db.ObjectId\n  createdAt DateTime @default(now())\n  project   Project  @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  projectId String   @db.ObjectId\n\n  @@unique([projectId, likedById])\n  @@index([likedById])\n  @@index([projectId])\n  @@map("likes")\n}\n\nmodel ProductCategory {\n  id       String    @id @default(auto()) @map("_id") @db.ObjectId\n  name     String    @unique\n  icon     String\n  imageUrl String?\n  products Product[]\n\n  @@map("productcategories")\n}\n\nmodel Product {\n  id               String            @id @default(auto()) @map("_id") @db.ObjectId\n  name             String\n  description      String\n  price            Float\n  inventory        Int\n  categoryId       String            @db.ObjectId\n  category         ProductCategory   @relation(fields: [categoryId], references: [id], onDelete: Cascade)\n  images           String[]\n  brand            String?\n  size             String?\n  howToUse         String?\n  amazonUrl        String?\n  flipkartUrl      String?\n  sourceType       String            @default("OWN")\n  createdAt        DateTime          @default(now())\n  updatedAt        DateTime          @updatedAt\n  projectMaterials ProjectMaterial[]\n\n  @@index([categoryId])\n  @@map("products")\n}\n\nmodel Order {\n  id                String            @id @default(auto()) @map("_id") @db.ObjectId\n  userId            String            @db.ObjectId\n  user              User              @relation(fields: [userId], references: [id], onDelete: Cascade)\n  products          OrderProduct[]\n  totalAmount       Float\n  paymentStatus     PaymentStatus     @default(PENDING)\n  createdAt         DateTime          @default(now())\n  updatedAt         DateTime          @updatedAt\n  transaction       Transaction       @relation(fields: [transactionId], references: [id])\n  transactionId     String            @db.ObjectId @unique\n  deliveryAddress   String?\n  fulfillmentStatus FulfillmentStatus @default(PENDING_DISPATCH)\n  courierName       String?\n  trackingNumber    String?\n  estimatedDelivery DateTime?\n  dispatchedAt      DateTime?\n\n  @@index([userId])\n  @@map("orders")\n}\n\ntype OrderProduct {\n  productId String @db.ObjectId\n  quantity  Int\n}\n\nenum FulfillmentStatus {\n  PENDING_DISPATCH\n  DISPATCHED\n  DELIVERED\n}\n\nenum PaymentStatus {\n  PENDING\n  COMPLETED\n  FAILED\n}\n\nmodel Wallet {\n  id           String        @id @default(auto()) @map("_id") @db.ObjectId\n  userId       String        @db.ObjectId @unique\n  user         User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  balance      Float         @default(0.0)\n  transactions Transaction[]\n\n  @@map("wallets")\n}\n\nmodel Transaction {\n  id        String          @id @default(auto()) @map("_id") @db.ObjectId\n  walletId  String          @db.ObjectId\n  wallet    Wallet          @relation(fields: [walletId], references: [id], onDelete: Cascade)\n  order     Order?\n  amount    Float\n  type      TransactionType\n  status    PaymentStatus?\n  createdAt DateTime        @default(now())\n\n  @@index([walletId])\n  @@map("transactions")\n}\n\nenum TransactionType {\n  DEBIT\n  CREDIT\n}\n\nmodel SiteContent {\n  id        String   @id @default(auto()) @map("_id") @db.ObjectId\n  key       String   @unique\n  value     Json\n  updatedAt DateTime @updatedAt\n  updatedBy String?\n\n  @@map("site_content")\n}\n\nmodel ContactMessage {\n  id        String    @id @default(auto()) @map("_id") @db.ObjectId\n  name      String\n  email     String\n  subject   String\n  message   String\n  source    String    @default("app")\n  status    String    @default("unread")\n  repliedAt DateTime?\n  repliedBy String?\n  createdAt DateTime  @default(now())\n\n  @@map("contact_messages")\n}\n\nmodel Material {\n  id             String   @id @default(auto()) @map("_id") @db.ObjectId\n  seqId          Int?\n  name           String\n  description    String?\n  imageUrl       String?\n  icon           String?\n  category       String\n  unit           String   @default("piece")\n  goinsPrice     Int\n  priceEstimate  Int?\n  amazonASIN     String?\n  amazonUrl      String?\n  showInShop     Boolean  @default(true)\n  showInPlanning Boolean  @default(true)\n  isActive       Boolean  @default(true)\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n  // AI-assisted Amazon matching (never auto-applied — see AmazonSuggestion)\n  amazonNeedsAttention Boolean   @default(false)\n  amazonAttentionReason String?\n  amazonLastCheckedAt   DateTime?\n\n  @@map("materials")\n}\n\n// A single AI-found Amazon candidate for one Material, awaiting admin\n// approval. Never auto-applied to the Material — approving/rejecting is\n// always a deliberate human action (backend/src/routes/materialsRoutes.ts\n// POST /admin/amazon-suggestions/:id/approve|reject).\nmodel AmazonSuggestion {\n  id                  String    @id @default(auto()) @map("_id") @db.ObjectId\n  materialId          String    @db.ObjectId\n  materialName        String\n  suggestedAsin        String?\n  suggestedTitle       String?\n  suggestedImageUrl    String?\n  suggestedPriceRupees Int?\n  // Gemini\'s best-effort visual check that the candidate\'s photo actually\n  // looks like the material (0-1). Null if verification wasn\'t run/failed —\n  // never blocks the suggestion, just informs the admin\'s decision.\n  imageConfidence      Float?\n  imageConfidenceNote  String?\n  searchedQuery        String?\n  // PENDING | APPROVED | REJECTED | NO_MATCH\n  status               String    @default("PENDING")\n  reason               String?\n  createdAt            DateTime  @default(now())\n  resolvedAt           DateTime?\n  resolvedByAdminId     String?   @db.ObjectId\n\n  @@index([materialId])\n  @@index([status])\n  @@map("amazon_suggestions")\n}\n\nmodel ProductSuggestion {\n  id                  String    @id @default(auto()) @map("_id") @db.ObjectId\n  childName           String?\n  userId              String?   @db.ObjectId\n  suggestion          String\n  category            String?\n  requestedGoinsPrice Int?\n  // What the child was working on when they suggested this, e.g.\n  // "Project: Solar Car (Electronics & Circuits)" — best-effort, captured\n  // client-side since a project draft isn\'t a DB record until upload.\n  projectContext      String?\n  // Auto-filled by the same AI scan job that handles Material ASIN gaps —\n  // a pre-fetched Amazon candidate for this suggestion, so an admin\n  // reviewing it already has a starting point instead of searching from\n  // scratch. Never auto-creates a Material — admin still does that by hand.\n  amazonAsinFound     String?\n  amazonTitleFound    String?\n  amazonImageUrlFound String?\n  amazonPriceFound    Int?\n  amazonSearchedAt    DateTime?\n  // pending: just submitted, not yet looked at\n  // approved: admin liked it, plans to add as a real Material\n  // added: admin actually created the Material — resolvedMaterialId links to it\n  // rejected: admin decided not to add it — adminNotes explains why\n  status             String    @default("pending")\n  resolvedMaterialId String?   @db.ObjectId\n  adminNotes         String?\n  resolvedAt         DateTime?\n  createdAt          DateTime  @default(now())\n\n  @@map("product_suggestions")\n}\n\nmodel PendingRegistration {\n  id            String   @id @default(auto()) @map("_id") @db.ObjectId\n  miniguruId    String   @unique\n  childName     String\n  age           Int\n  grade         String?\n  guardianName  String?\n  guardianEmail String\n  guardianPhone String?\n  passwordHash  String\n  otpHash       String\n  otpExpiry     DateTime\n  createdAt     DateTime @default(now())\n  @@map("pending_registrations")\n}\n\nmodel VideoRating {\n  id            String   @id @default(auto()) @map("_id") @db.ObjectId\n  videoId       String   @db.ObjectId\n  raterId       String   @db.ObjectId\n  creatorId     String   @db.ObjectId\n  sturdy        Boolean  @default(false)\n  creative      Boolean  @default(false)\n  functional    Boolean  @default(false)\n  resourceful   Boolean  @default(false)\n  documented    Boolean  @default(false)\n  isCrossSchool Boolean  @default(false)\n  goinsAwarded  Int      @default(0)\n  createdAt     DateTime @default(now())\n\n  @@unique([videoId, raterId])\n  @@map("video_ratings")\n}\n\nmodel Happening {\n  id              String    @id @default(auto()) @map("_id") @db.ObjectId\n  title           String\n  description     String\n  date            DateTime\n  city            String?\n  schoolName      String?   // auto-filled from submitter\'s guardianInfo.institutionName — never typed manually\n  emoji           String    @default("🏫")\n  tag             String    @default("Update")   // NEW / UPCOMING / MILESTONE / AWARD / PAST\n  tagColor        String?\n  imageUrl        String?\n  status          String    @default("PENDING")  // PENDING | APPROVED | REJECTED\n  submittedById   String?   @db.ObjectId          // null = admin-authored (auto-approved)\n  submittedByName String?\n  approvedById    String?   @db.ObjectId\n  approvedAt      DateTime?\n  rejectionReason String?\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n\n  @@index([status])\n  @@index([submittedById])\n  @@map("happenings")\n}\n\nmodel Challenge {\n  id              String    @id @default(auto()) @map("_id") @db.ObjectId\n  title           String\n  description     String\n  category        String\n  categoryEmoji   String?\n  difficulty      String    @default("Medium")\n  goinsReward     Int       @default(100)\n  endDate         DateTime\n  participants    Int       @default(0)\n  color           String?\n  lifecycleStatus String    @default("upcoming")  // ongoing | upcoming | past — DISPLAY status\n  status          String    @default("PENDING")   // PENDING | APPROVED | REJECTED — MODERATION status\n  audience        String    @default("ALL")       // ALL | OWN_SCHOOL\n  restrictedToUserId String? @db.ObjectId          // set when audience=OWN_SCHOOL — the submitting teacher/school\'s own User.id\n  submittedById   String?   @db.ObjectId           // null = admin-authored (auto-approved, always ALL)\n  submittedByName String?\n  approvedById    String?   @db.ObjectId\n  approvedAt      DateTime?\n  rejectionReason String?\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n\n  @@index([status])\n  @@index([audience])\n  @@index([submittedById])\n  @@map("challenges")\n}\n\n// Real Daily Quest (Aug 2026) — replaces a purely decorative, hardcoded\n// home-screen card ("3/5 • +50 pts", frozen, never actually changed for\n// anyone). Task: watch 3 project videos to real completion today (reuses\n// the existing 75%-watched view-tracking, not a separate counting system).\n// One record per user per day; DAILY_QUEST_TARGET/REWARD are the only two\n// numbers to touch if this needs tuning later.\nmodel DailyQuestProgress {\n  id            String   @id @default(auto()) @map("_id") @db.ObjectId\n  userId        String   @db.ObjectId\n  date          String   // "YYYY-MM-DD" — plain string compare, no timezone math\n  videosWatched Int      @default(0)\n  completed     Boolean  @default(false)\n  streakAtCompletion Int @default(0) // User.currentStreak snapshot at the moment this quest completed\n  createdAt     DateTime @default(now())\n\n  @@unique([userId, date])\n  @@map("daily_quest_progress")\n}\n\nmodel GoinTopUpRequest {\n  id                  String    @id @default(auto()) @map("_id") @db.ObjectId\n  requesterId         String    @db.ObjectId\n  requesterName       String\n  amount              Int\n  reason              String?\n  projectDraftContext String?\n  status              String    @default("PENDING")\n  // DIRECT_TOPUP = child/mentor directly asks for bonus Goins — approving\n  // this CREDITS the amount (original behavior, unchanged).\n  // MATERIAL_OVERSPEND = auto-created when a project\'s material cost took\n  // the child\'s balance negative — this is an AUDIT RECORD, not a request\n  // for free Goins. The deduction already happened; approving it never\n  // credits anything. The debt persists and is repaid by earning more\n  // Goins normally, per the founder\'s explicit design (Aug 2026).\n  requestType         String    @default("DIRECT_TOPUP")\n  decidedById         String?   @db.ObjectId\n  decidedByRole       String?\n  decidedAt           DateTime?\n  denialReason        String?\n  createdAt           DateTime  @default(now())\n\n  @@index([requesterId])\n  @@index([status])\n  @@map("goin_topup_requests")\n}')

